commands.command:
cat > /tmp/aac-blind-cold-run.mjs <<'EOF'
import {createFileEngine} from '/workspace/scratch/27fa6ff6c3a9/REDOWN/extension/file-engine/engine.mjs';
import {memoryAdapter} from '/workspace/scratch/27fa6ff6c3a9/REDOWN/extension/file-engine/adapters/memory.mjs';
import {fileStore} from '/workspace/scratch/27fa6ff6c3a9/REDOWN/scripts/r2-lab/file-store.mjs';
import {readFile,writeFile,mkdtemp} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const dir=await mkdtemp('/tmp/aac-blind-cold-'), path=dir+'/journal.json',store=fileStore(path),engine=createFileEngine({store,adapters:[memoryAdapter(store,'fake-r2')]});
const identity=key=>({provider:'fake-r2',account:'demo',container:'sandbox',key});
const run=(operation,props)=>engine.run({apiVersion:'0.2.0',operation,idempotencyKey:'blind-'+operation,...props});
const browse=await run('list',{source:identity('')});
const locate=await engine.run({apiVersion:'0.2.0',operation:'list',idempotencyKey:'blind-locate',source:identity('Documents/'),query:'Example'});
const key=locate.result.objects[0].key;
const copy=await run('copy',{source:identity(key),destination:identity('Blind-copy.txt')});
const raw=JSON.parse(await readFile(path,'utf8'));
const object=k=>raw.objects.find(o=>o.provider==='fake-r2'&&o.account==='demo'&&o.container==='sandbox'&&o.key===k);
const bytes=o=>o.bytesBase64!==undefined?Buffer.from(o.bytesBase64,'base64'):Buffer.from(o.content);
const hash=b=>createHash('sha256').update(b).digest('hex');
const a=bytes(object(key)),b=bytes(object('Blind-copy.txt'));
const output={directory:dir,capabilities:engine.describe(),browse,locate,copy,independentVerification:{method:'Direct fresh journal file read; bypass engine and adapter results, shared simulated backing store',sourceSha256:hash(a),destinationSha256:hash(b),sourceBytes:a.length,destinationBytes:b.length,equal:a.equals(b)}};
await writeFile('/tmp/aac-blind-cold-execution.json',JSON.stringify(output,null,2));
await writeFile('/tmp/aac-blind-cold-resources.json',JSON.stringify(await engine.resources.exportEvidence(),null,2));
console.log(JSON.stringify({capabilities:output.capabilities,browse:browse.result,locate:locate.result,copy:{id:copy.id,state:copy.state,receipt:copy.receipt},independentVerification:output.independentVerification}));
EOF
node /tmp/aac-blind-cold-run.mjs
